CREATE TABLE schema_migrations (version INTEGER PRIMARY KEY, checksum TEXT NOT NULL, applied_at TEXT NOT NULL);
CREATE TABLE app_users (id TEXT PRIMARY KEY, display_name TEXT NOT NULL);
CREATE TABLE workspaces (id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE workspace_members (workspace_id TEXT NOT NULL REFERENCES workspaces(id), user_id TEXT NOT NULL REFERENCES app_users(id), PRIMARY KEY(workspace_id,user_id));
CREATE TABLE engine_releases (id TEXT PRIMARY KEY, source_commit TEXT NOT NULL, source_hash TEXT NOT NULL, manifest_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE projects (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), canonical_id TEXT NOT NULL, title TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(workspace_id,canonical_id), UNIQUE(id,workspace_id));
CREATE TABLE project_versions (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), version INTEGER NOT NULL CHECK(version>0), config_hash TEXT NOT NULL, snapshot_locator TEXT NOT NULL, manifest_json TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(project_id,version), UNIQUE(id,project_id));
CREATE TABLE jobs (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), version_id TEXT NOT NULL, engine_id TEXT NOT NULL REFERENCES engine_releases(id), operation TEXT NOT NULL, idempotency_key TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('QUEUED','RUNNING','USER_ACTION_REQUIRED','COMPLETE','FAILED','CANCELLED')), message TEXT NOT NULL, progress INTEGER NOT NULL CHECK(progress BETWEEN 0 AND 100), attempts INTEGER NOT NULL DEFAULT 0 CHECK(attempts>=0), worker_token TEXT, heartbeat DOUBLE PRECISION, result_json TEXT, diagnostic_locator TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(id,project_id,version_id), UNIQUE(project_id,version_id,operation,idempotency_key), FOREIGN KEY(version_id,project_id) REFERENCES project_versions(id,project_id));
CREATE UNIQUE INDEX jobs_active_request ON jobs(project_id,version_id,operation) WHERE state IN ('QUEUED','RUNNING');
CREATE UNIQUE INDEX jobs_one_running_per_project ON jobs(project_id) WHERE state='RUNNING';
CREATE TABLE artifacts (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), version_id TEXT NOT NULL, job_id TEXT NOT NULL, logical_name TEXT NOT NULL, artifact_type TEXT NOT NULL, version INTEGER NOT NULL CHECK(version>0), status TEXT NOT NULL CHECK(status IN ('AVAILABLE','WITHDRAWN')), checksum TEXT NOT NULL, storage_locator TEXT NOT NULL, engine_id TEXT NOT NULL REFERENCES engine_releases(id), approval_state TEXT NOT NULL CHECK(approval_state IN ('UNREVIEWED','APPROVED','REJECTED')), created_at TEXT NOT NULL, UNIQUE(project_id,logical_name,version), UNIQUE(id,project_id,version_id), FOREIGN KEY(job_id,project_id,version_id) REFERENCES jobs(id,project_id,version_id));
CREATE TABLE gates (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, workspace_id TEXT NOT NULL, version_id TEXT NOT NULL, gate_type TEXT NOT NULL, required_operation TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('PENDING','APPROVED','REJECTED')), decision TEXT, reviewer_id TEXT, decided_at TEXT, artifact_id TEXT, rationale TEXT, created_at TEXT NOT NULL, FOREIGN KEY(project_id,workspace_id) REFERENCES projects(id,workspace_id), FOREIGN KEY(version_id,project_id) REFERENCES project_versions(id,project_id), FOREIGN KEY(workspace_id,reviewer_id) REFERENCES workspace_members(workspace_id,user_id), FOREIGN KEY(artifact_id,project_id,version_id) REFERENCES artifacts(id,project_id,version_id), CHECK((status='PENDING' AND reviewer_id IS NULL AND decision IS NULL AND decided_at IS NULL) OR (status<>'PENDING' AND reviewer_id IS NOT NULL AND decision=status AND decided_at IS NOT NULL)));
CREATE TABLE audit_events (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, workspace_id TEXT NOT NULL, actor_id TEXT, event_type TEXT NOT NULL, object_id TEXT NOT NULL, detail_json TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(project_id,workspace_id) REFERENCES projects(id,workspace_id), FOREIGN KEY(workspace_id,actor_id) REFERENCES workspace_members(workspace_id,user_id));
CREATE INDEX jobs_queue ON jobs(state,created_at);
CREATE INDEX gates_version ON gates(project_id,version_id,required_operation,status);
